<script setup lang="ts">import{onMounted,onBeforeUnmount,ref,watch}from"vue";import{getCurrentWindow}from"@tauri-apps/api/window";import*as api from"../api/note";const id=new URLSearchParams(location.search).get("note")!,note=ref<any>(null),status=ref("");let timer:number|undefined;onMounted(async()=>note.value=await api.get(id));watch(note,()=>{if(!note.value)return;clearTimeout(timer);timer=window.setTimeout(async()=>{status.value="保存中…";note.value=await api.update(id,{title:note.value.title,content:note.value.content,collapsed:note.value.collapsed,alwaysOnTop:note.value.alwaysOnTop});status.value="已保存"},500)},{deep:true});onBeforeUnmount(()=>clearTimeout(timer));async function dock(){await api.dock(id)}async function toggle(){note.value.collapsed=!note.value.collapsed;await getCurrentWindow().setSize(new (await import('@tauri-apps/api/dpi')).LogicalSize(360,note.value.collapsed?46:280))}</script><template><div v-if="note" class="floating" :class="{collapsed:note.collapsed}"><header data-tauri-drag-region><input v-model="note.title" class="floating-title"><button @click="toggle">{{note.collapsed?'▾':'▴'}}</button><button @click="dock">×</button></header><textarea v-if="!note.collapsed" v-model="note.content" class="input"></textarea><small v-if="!note.collapsed">{{status}}</small></div></template>
